const wait = (ms, v) => new Promise(r => setTimeout(() => r(v), ms));

async function main() {
  // forEach does not wait for async callbacks
  nums.forEach(async n => { await wait(10, n); console.log("late forEach", n); });
  console.log("after forEach (nothing awaited yet)");
  await wait(30);
  // for...of awaits each item in sequence
